function Invoke-DKillFastReleaseDockerVhdLocks {
    [CmdletBinding()]
    param([ValidateRange(300,30000)][int]$Milliseconds = 2500)

    $failures = @()
    $actions = @()
    $watch = [Diagnostics.Stopwatch]::StartNew()
    $vhd = 'C:\ProgramData\DockerDesktop\vm-data\DockerDesktop.vhdx'
    $vmId = $null
    $expired = { $watch.ElapsedMilliseconds -ge $Milliseconds }

    if(-not $script:DKillFastIsAdmin) {
        Write-DKillFastLine 'DKILL_VHD_LOCK_SKIP administrator rights are required' Yellow
        return [pscustomobject]@{ Succeeded=$false; Skipped=$true; Actions=@(); Failures=@('administrator rights are required') }
    }

    Write-Progress -Activity 'Docker VHD lock release' -Status 'Inspecting DockerDesktopVM' -PercentComplete 10
    try {
        if(Get-Module -ListAvailable -Name Hyper-V) {
            Import-Module Hyper-V -ErrorAction Stop
            $vm = Get-VM -Name 'DockerDesktopVM' -ErrorAction SilentlyContinue
            if($vm) {
                $vmId = ([string]$vm.Id).ToUpperInvariant()
                Write-DKillFastLine ("DKILL_VHD_LOCK_OK DockerDesktopVM state={0}" -f $vm.State) DarkCyan
                if($vm.State -ne 'Off' -and -not (& $expired)) {
                    Stop-VM -Name 'DockerDesktopVM' -TurnOff -Force -ErrorAction Stop
                    $actions += 'hyperv-stop'
                    Write-DKillFastLine 'DKILL_VHD_LOCK_OK DockerDesktopVM stopped' DarkCyan
                }
            } else {
                Write-DKillFastLine 'DKILL_VHD_LOCK_INFO DockerDesktopVM not registered' DarkCyan
            }
        } else {
            Write-DKillFastLine 'DKILL_VHD_LOCK_INFO Hyper-V module unavailable' DarkCyan
        }
    } catch {
        $failures += "hyperv: $($_.Exception.Message)"
        Write-DKillFastLine ("DKILL_VHD_LOCK_WARN Hyper-V stage failed: {0}" -f $_.Exception.Message) Yellow
    }

    if(-not (& $expired)) {
        Write-Progress -Activity 'Docker VHD lock release' -Status 'Removing VM provider lock' -PercentComplete 30
        try {
            $vmMgmt = Get-CimInstance -Namespace root\virtualization\v2 -ClassName Msvm_VirtualSystemManagementService -ErrorAction Stop
            $dockerVm = Get-CimInstance -Namespace root\virtualization\v2 -ClassName Msvm_ComputerSystem -ErrorAction Stop | Where-Object { $_.ElementName -eq 'DockerDesktopVM' } | Select-Object -First 1
            if($vmMgmt -and $dockerVm) {
                $result = Invoke-CimMethod -InputObject $vmMgmt -MethodName DestroySystem -Arguments @{ AffectedSystem = $dockerVm } -ErrorAction Stop
                if($result.ReturnValue -eq 0) {
                    $actions += 'provider-destroy'
                    Write-DKillFastLine 'DKILL_VHD_LOCK_OK VM provider released DockerDesktopVM' DarkCyan
                } else {
                    $failures += "provider-destroy return=$($result.ReturnValue)"
                    Write-DKillFastLine ("DKILL_VHD_LOCK_WARN VM provider returned {0}" -f $result.ReturnValue) Yellow
                }
            } else {
                Write-DKillFastLine 'DKILL_VHD_LOCK_INFO no Docker VM provider object remained' DarkCyan
            }
        } catch {
            $failures += "provider: $($_.Exception.Message)"
            Write-DKillFastLine ("DKILL_VHD_LOCK_WARN VM provider stage failed: {0}" -f $_.Exception.Message) Yellow
        }
    }

    if(-not (& $expired)) {
        Write-Progress -Activity 'Docker VHD lock release' -Status 'Stopping matching vmwp processes' -PercentComplete 50
        try {
            $vmwp = @(Get-CimInstance Win32_Process -Filter "Name='vmwp.exe'" -ErrorAction Stop | Where-Object {
                $commandLine = [string]$_.CommandLine
                ($vmId -and $commandLine.ToUpperInvariant().Contains($vmId)) -or $commandLine -match '(?i)DockerDesktopVM|DockerDesktop\.vhdx|\\DockerDesktop\\vm-data'
            })
            foreach($process in $vmwp) {
                try {
                    Stop-Process -Id $process.ProcessId -Force -ErrorAction Stop
                    $actions += "vmwp:$($process.ProcessId)"
                    Write-DKillFastLine ("DKILL_VHD_LOCK_OK vmwp pid={0} stopped" -f $process.ProcessId) DarkCyan
                } catch {
                    $failures += "vmwp:$($process.ProcessId): $($_.Exception.Message)"
                    Write-DKillFastLine ("DKILL_VHD_LOCK_FAIL vmwp pid={0}: {1}" -f $process.ProcessId,$_.Exception.Message) Red
                }
            }
        } catch {
            $failures += "vmwp-discovery: $($_.Exception.Message)"
            Write-DKillFastLine ("DKILL_VHD_LOCK_WARN vmwp discovery failed: {0}" -f $_.Exception.Message) Yellow
        }
    }

    if(-not (& $expired) -and (Test-Path -LiteralPath $vhd)) {
        Write-Progress -Activity 'Docker VHD lock release' -Status 'Dismounting Docker VHD' -PercentComplete 65
        try {
            if(Get-Command Dismount-VHD -ErrorAction SilentlyContinue) {
                Dismount-VHD -Path $vhd -ErrorAction Stop
                $actions += 'dismount-vhd'
                Write-DKillFastLine 'DKILL_VHD_LOCK_OK DockerDesktop.vhdx dismounted' DarkCyan
            } else {
                Write-DKillFastLine 'DKILL_VHD_LOCK_INFO Dismount-VHD unavailable' DarkCyan
            }
        } catch {
            $failures += "dismount-vhd: $($_.Exception.Message)"
            Write-DKillFastLine ("DKILL_VHD_LOCK_WARN VHD dismount failed: {0}" -f $_.Exception.Message) Yellow
        }
    }

    if(-not (& $expired)) {
        Write-Progress -Activity 'Docker VHD lock release' -Status 'Releasing HCS VM locks' -PercentComplete 80
        $hcs = Join-Path $env:SystemRoot 'System32\hcsdiag.exe'
        if(Test-Path -LiteralPath $hcs) {
            try {
                $hcsList = @(& $hcs list 2>&1)
                if($LASTEXITCODE -ne 0) { throw "hcsdiag list exit=$LASTEXITCODE" }
                $ids = @()
                for($index=0; $index -lt $hcsList.Count; $index++) {
                    $line = [string]$hcsList[$index]
                    if($line -match '^[0-9A-Fa-f-]{36}$') {
                        $next = if($index + 1 -lt $hcsList.Count) { [string]$hcsList[$index + 1] } else { '' }
                        if($next -match 'VMMS' -and $next -notmatch 'WSL') { $ids += $line.Trim() }
                    }
                }
                foreach($id in $ids) {
                    if(& $expired) { break }
                    $null = & $hcs kill $id 2>&1
                    if($LASTEXITCODE -eq 0) {
                        $actions += "hcs:$id"
                        Write-DKillFastLine ("DKILL_VHD_LOCK_OK HCS VM {0} stopped" -f $id) DarkCyan
                    } else {
                        $failures += "hcs:$id exit=$LASTEXITCODE"
                        Write-DKillFastLine ("DKILL_VHD_LOCK_WARN HCS VM {0} exit={1}" -f $id,$LASTEXITCODE) Yellow
                    }
                }
            } catch {
                $failures += "hcs: $($_.Exception.Message)"
                Write-DKillFastLine ("DKILL_VHD_LOCK_WARN HCS stage failed: {0}" -f $_.Exception.Message) Yellow
            }
        }
    }

    if(& $expired) {
        $failures += 'time budget exhausted'
        Write-DKillFastLine ("DKILL_VHD_LOCK_INCOMPLETE time budget exhausted after {0}ms" -f $watch.ElapsedMilliseconds) Yellow
    } else {
        Write-Progress -Activity 'Docker VHD lock release' -Status 'Final Docker process pass' -PercentComplete 92
        $stopReceipt = Stop-DKillFastDocker
        if(-not $stopReceipt.Succeeded) { $failures += 'Docker process stop reported incomplete' }
    }
    $watch.Stop()
    Write-Progress -Activity 'Docker VHD lock release' -Completed
    $succeeded = $failures.Count -eq 0
    Write-DKillFastLine ("DKILL_VHD_LOCK_{0} actions={1} failures={2} elapsed_ms={3}" -f $(if($succeeded){'OK'}else{'INCOMPLETE'}),$actions.Count,$failures.Count,$watch.ElapsedMilliseconds) $(if($succeeded){'Green'}else{'Yellow'})
    [pscustomobject]@{ Succeeded=$succeeded; Skipped=$false; Actions=@($actions); Failures=@($failures); ElapsedMilliseconds=$watch.ElapsedMilliseconds }
}

